#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-or-later
#
# Writes the standards page of every module that declares its standards:
# docs/reference/modules/<moduleId>/standards.md from
# src/Modules/<Module>/standards.json, one table row per standard
# (docs/module-developers/watching-standards.md). The pages are committed, and
# the standards gate of .devkit/gates.sh fails when one differs from what this
# script writes.
#
# Usage:  bash .github/scripts/render-standards.sh [<repository root> [<output root>]]
#
# Both default to the repository root; the pages are written below
# <output root>/docs/reference/modules/. Needs jq.
set -uo pipefail

root="${1:-$(git rev-parse --show-toplevel)}"
out="${2:-${root}}"
failed=0
date_pattern='^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
module_id_pattern='^[a-z0-9]+(-[a-z0-9]+)*$'

# jq on Windows ends its lines with CR; strip it so the pages are LF only.
field() { jq -r "$2 // empty" <<< "$1" | tr -d '\r'; }

# cell <date or empty>: a table cell for an optional date.
cell() { if [ -n "$1" ]; then printf '%s' "$1"; else printf '—'; fi; }

# source <standard as JSON>: links to the release or to the pages a review reads.
source_links() {
  local standard="$1" repo version
  repo="$(field "${standard}" '.github')"
  version="$(field "${standard}" '.version')"
  if [ -n "${repo}" ]; then
    printf '[%s](https://github.com/%s/releases/tag/%s)' "${repo}" "${repo}" "${version}"
  else
    field "${standard}" '.urls[]' | sed 's/.*/<&>/' | paste -s -d ' ' -
  fi
}

# render <file> <path>: prints the page of one standards.json, or fails.
render() {
  local file="$1" path="$2" module_id standards standard name version from until
  module_id="$(jq -r '.moduleId // empty' "${path}" | tr -d '\r')"
  if ! [[ "${module_id}" =~ ${module_id_pattern} ]]; then
    echo "::error::${file}: moduleId \"${module_id}\" is missing or not a module id" >&2
    return 1
  fi
  standards="$(jq -c '.standards[]' "${path}" | tr -d '\r')" || return 1
  cat <<PAGE
<!-- Generated by .github/scripts/render-standards.sh from ${file}. Do not edit. -->
# Standards of the ${module_id} module

The external standards the \`${module_id}\` module implements, and from when
until when the implemented version is valid, as its source states it. A dash
means the source states no date. The page is generated from
\`${file}\`; see
[watching standards](../../../module-developers/watching-standards.md).

| Standard | Version | Valid from | Valid until | Source |
|---|---|---|---|---|
PAGE
  while IFS= read -r standard; do
    name="$(field "${standard}" '.name')"
    version="$(field "${standard}" '.version')"
    from="$(field "${standard}" '.validFrom')"
    until="$(field "${standard}" '.validUntil')"
    for date in "${from}" "${until}"; do
      if [ -n "${date}" ] && ! [[ "${date}" =~ ${date_pattern} ]]; then
        echo "::error::${file}: ${name} has a date \"${date}\" that is not YYYY-MM-DD" >&2
        return 1
      fi
    done
    printf '| %s | `%s` | %s | %s | %s |\n' \
      "${name}" "${version}" "$(cell "${from}")" "$(cell "${until}")" "$(source_links "${standard}")"
  done <<< "${standards}"
}

shopt -s nullglob
for path in "${root}"/src/Modules/*/standards.json; do
  file="${path#"${root}"/}"
  if ! page="$(render "${file}" "${path}")"; then
    failed=1
    continue
  fi
  module_id="$(jq -r '.moduleId' "${path}" | tr -d '\r')"
  target="${out}/docs/reference/modules/${module_id}/standards.md"
  mkdir -p "$(dirname "${target}")"
  printf '%s\n' "${page}" > "${target}"
  echo "${target#"${out}"/}"
done

exit "${failed}"
